          "oneLine": "提出无偏 large-N 方法，研究密度波和超导不稳定性产生的 vestigial order 竞争。",
          "problem": "多分量主序的复合序参量在 large-N 解耦中是否会引入人为偏置？",
          "result": "结果表明，无偏处理可以同时保留多个 vestigial 通道，并给出密度波与超导相关剩余序之间的竞争关系。",
