          "oneLine": "研究 Kitaev-Hubbard 模型中掺杂诱导的能隙内态与自旋激发之间的关系。",
          "problem": "Mott 绝缘体中的掺杂能隙内态是否直接反映底层自旋激发谱？",
          "result": "结果表明，能隙内态的动量色散会随 Kitaev 各向异性改变，并与对应自旋激发能隙和分支结构相匹配。",
          "methods": "Kitaev-Hubbard 模型与 cluster perturbation theory。",
