          "oneLine": "发现铜氧化物中超导会增强 CDW 的相位相干性。",
          "problem": "铜氧化物中超导一定削弱 CDW，还是会同时增强其相位相干？",
          "result": "结果表明，多类铜氧化物在 Tc 以下出现系统性的 CDW 相位相干增强，并表现出波矢锁定和峰宽不展宽。",
          "methods": "共振软 X 射线散射与动量峰形相干性分析。",
