          "oneLine": "本文关注强关联电子体系中的磁性和自旋涨落与输运性质。",
          "problem": "强关联电子体系中的磁性和自旋涨落与输运性质如何反映关联效应和对称性破缺？",
          "result": "结果表明，磁性相互作用和低能自旋涨落会显著影响该体系的相行为。",
