          "oneLine": "提出三维自旋三聚体网络中由增强有效各向异性稳定的量子自旋液体候选。",
          "problem": "三维自旋三聚体晶格中是否能由有效各向异性稳定量子自旋液体？",
          "result": "结果表明，KBa3Ca4Cu3V7O28 在低温下没有磁冻结或对称性破缺，呈现无能隙动态基态，是三维量子自旋液体候选。",
          "methods": "Monte Carlo 模拟、中子散射实验、NMR 谱学。",
