          "oneLine": "本文关注强关联电子体系中的磁性和自旋涨落与电子-晶格耦合。",
          "problem": "强关联电子体系中的磁性和自旋涨落与电子-晶格耦合如何由相互作用、晶格效应或对称性共同决定？",
