          "oneLine": "本文关注强关联电子体系中的磁性和自旋涨落。",
          "problem": "强关联电子体系中的磁性和自旋涨落如何由相互作用、晶格效应或对称性共同决定？",
          "result": "结果表明，磁性相互作用和低能自旋涨落会显著影响该体系的相行为。",
          "methods": "NMR 谱学。",
          "why": "包含 NMR 线索，适合关注磁性和低能涨落。",
          "summary": "本文关注强关联电子体系中的磁性和自旋涨落。",
          "abstract": "We report a comprehensive NMR study of the chiral square-cupola antiferromagnet Pb(TiO)Cu$_4$(PO$_4$)$_4$ and compare its microscopic hyperfine and local-field parameters with the Ba/Sr analogues in the $A$(TiO)Cu$_4$(PO$_4$)$_4$ family. Above $T_{\\rm N}\\simeq 6.7$ K, the $^{31}$P Knight shift tracks the bulk susceptibility and yields nearly isotropic transferred hyperfine couplings $H_{\\rm hf}^{[010]}=6.77(3)$ and $H_{\\rm hf}^{[001]}=6.19(3)$ kOe/$\\mu_{\\rm B}$. Below $T_{\\rm N}$, the frequency-swept $^{31}$P spectrum splits into three lines, in contrast to the four-line pattern reported for BaTCPO. The line separation tracks the onset of the static $^{31}$P internal field with a power-law exponent $\\beta\\simeq 0.23$, consistent with quasi-two-dimensional criticality. Crystal-rotation $^{31}$P NMR in the ordered state resolves all eight symmetry-related P sites and their site-dependent anisotropy. In the ordered state, zero-field $^{63,65}$Cu NMR gives a Cu-site internal field $B_{\\rm int}=14.50(6)$ T and a quadrupole frequency $\\nu_Q=32.72(5)$ MHz, while point-charge electric-field-gradient calculations including Sternheimer corrections yield an on-site Cu hole occupancy $n_d=0.20(4)$, consistent with a ligand-hole-dominated charge-transfer character. Comparing PbTCPO with BaTCPO and SrTCPO, we find that the transferred hyperfine coupling $H_{\\rm hf}$ varies across the series, reflecting changes in local Cu-O-P covalency, whereas the ordered-state $^{31}$P internal field in PbTCPO is $69.5$ mT, considerably higher than in BaTCPO ($35.6$ mT) and SrTCPO ($34.6$ mT). This enhancement is not captured by dipolar terms alone and points to the combined effects of transferred contributions and stacking-dependent cancellation.",
