          "abstract": "We extend the multilayer model of \\etal{Kubo} for superconductor-insulator-superconductor (SIS) structures in two ways: first, by generalizing it to arbitrary sequences of layers of arbitrary type, i.e. superconducting, normal conducting, and insulating; and second, by accounting for all contributions, including ohmic losses and dielectric effects. We examine the maximum applicable field for $(\\text{SI})^n\\text{S}$ structures. We find that the optimum configuration corresponds to the $n=1$ case. However, the thickness of the superconducting coating layers can be reduced to below their penetration depth with minor performance penalty. We discuss the ability to model transitions in SS bilayers by introducing a set of virtual layers that represent the transition region through interpolated parameters. We find degradation of the maximum applicable field with thicker transition layers, and a larger effective penetration depth of the electromagnetic fields. Furthermore, the surface impedance of the multilayer structure is calculated using the Leontovich boundary condition, yielding a formulation suitable for integration into finite element simulations. Additionally, the Poynting theorem is used to determine the loss contributions of individual layers.",
