          "oneLine": "用 Josephson 扫描隧穿谱研究 kagome 超导体在深点接触极限下的局域超导响应。",
          "problem": "深点接触极限下的 Josephson 谱如何影响对 kagome 超导体零偏压电导的解读？",
          "result": "结果表明，零偏压电导会偏离常规二次标度并出现饱和，主要受串联电阻影响；同时给出了用 JSTM 探测低温 PDW 态的合适工作窗口。",
          "methods": "Josephson 扫描隧穿谱与点接触输运分析。",
          "why": "直接服务于 kagome 超导体中配对相干性和可能 PDW 态的局域探测。",
          "summary": "用 Josephson 扫描隧穿谱研究 kagome 超导体在深点接触极限下的局域超导响应。",
          "abstract": "Josephson scanning tunneling microscopy (JSTM) has emerged as an important technique for probing the superconducting order parameter at the atomic scale. However, the Josephson current in JSTM may behave quite differently when the coupling strength varies. Here, we push the junction to the deep point-contact regime, reaching a normal-state junction resistance of only 0.15 $h/2e^2 \\simeq 2~{\\rm k}\\Omega$. We demonstrate, using kagome superconductors, that the zero-bias conductance, a key characteristic of the Josephson current, deviates strongly from the quadratic dependence on the normal-state conductance upon entering the deep point-contact regime. Furthermore, we observe a striking saturation of the zero-bias conductance, which we show arises from the series resistance in the circuit. This also serves as a cautious reminder when interpreting zero-bias conductance saturation or quantization in studies of exotic physics such as that of Majorana zero modes if the tip-sample junction resistance is extremely small. Finally, we identify an optimum regime where JSTM can be used as an atomic-scale probe for studying pair-density wave states in materials with low superconducting transition temperature, such as AV3Sb5 kagome superconductors.",
          "priorityReason": "直接服务于 kagome 超导体中配对相干性和可能 PDW 态的局域探测。",
