          "abstract": "Competing interactions, non-trivial electronic band topology, quantum fluctuations, and the interplay between emergent degrees of freedom in frustrated quantum materials can give rise to a wide range of exotic phenomena. Glassy dynamics, originally studied in amorphous materials and biological systems, has recently attracted considerable interest in quantum condensed matter, particularly in relation to the collective behavior of spins, quasiparticle excitations, and topological spin textures. Here, we investigate the emergence of unconventional glassy spin dynamics in a broad class of frustrated quantum materials, where spin freezing exhibit distinct signatures in both thermodynamic and microscopic measurements. Using a comprehensive set of experimental probes, including thermodynamic, NMR, ($\\mu$SR), and neutron scattering, we identify characteristic signatures of topological spin-glass behavior and these complementary techniques reveal unconventional spin dynamics, short-range spin correlations, emergent low-energy excitations, and glassy behavior of topological origins, distinguishing these states from conventional spin glasses and disordered magnets. Furthermore, we discuss the role of hydrodynamic spin modes in governing glassy dynamics and the emergence of spin-jam states in frustrated lattices, providing a unified framework for understanding unconventional spin freezing of topological origin and bridging experimental observations with theoretical models. This review aims to advance our understanding of collective many-body phenomena arising from competing interactions, topological defects, collective excitations, quantum entanglement, and symmetry constraints. Such insights may facilitate the discovery and design of novel quantum materials and help address fundamental questions in contemporary condensed matter physics, with potential implications for future quantum technologies.",
          "priorityReason": "为受挫磁性材料中的玻璃化动力学和自旋阻塞态提供统一图像。",
