          "categories": [
            "cond-mat.supr-con"
          ],
          "important": false,
          "score": 0,
          "oneLine": "研究质子辐照如何增强 Hg 系铜氧化物单晶的临界电流密度 Jc。",
          "problem": "质子辐照能否通过引入钉扎中心提升高温超导单晶的 Jc？",
          "result": "结果表明，适当质子辐照可增强涡旋钉扎，从而提高临界电流密度。",
          "methods": "质子辐照、磁化测量与临界电流分析。",
          "why": "偏向高温超导材料应用，但也能提供缺陷调控超导性能的线索。",
          "summary": "研究质子辐照如何增强 Hg 系铜氧化物单晶的临界电流密度 Jc。",
          "abstract": "Critical current density is the key parameter for the practical application of superconductivity. In this study, 3 MeV proton irradiation experiments were conducted on HgBa$_2$Ca$_2$Cu$_3$O$_8$$_+$$_\\delta$ single crystals to introduce pinning centers. The critical current density is found to be strongly enhanced after the irradiation with its maximum at a dose of 1$\\times$10$^{16}$/cm$^2$, where the self-field critical current density at 2 K is enhanced from 5.5 MA/cm$^2$ to 26 MA/cm$^2$. At 77 K, the self-field critical current density for all irradiated crystals is over 0.1 MA/cm$^2$. The power-law dependence of the critical current density on the magnetic field is observed after irradiation, with a large power-law exponent $\\alpha$ close to 1. A monotonic magnetic field dependence of the normalized magnetic relaxation rate is observed, which could be attributed to the low irreversibility field caused by the large anisotropy in Hg1223 single crystals. Through the analysis of the pinning force density of the crystal before and after irradiation, a clear mechanism change has been observed.",
          "priorityReason": "偏向高温超导材料应用，但也能提供缺陷调控超导性能的线索。",
